create extension if not exists pgcrypto; create table if not exists public.vgi_visitors(id uuid primary key default gen_random_uuid(), visitor_key text unique not null, first_seen_at timestamptz default now(), last_seen_at timestamptz default now(), visit_count bigint default 1, country_code text, country_name text, region_name text, city text, timezone text, language text, browser text, operating_system text, device_class text, attributes jsonb default '{}'::jsonb); alter table public.vgi_visitors enable row level security;;
